import type {Metadata} from 'next';

import {getTranslations} from 'next-intl/server';

import {Locale} from '@/types/locale';

import {defaultLocale, locales} from '@/config';

export const siteUrl = (
    process.env.NEXT_PUBLIC_SITE_URL ?? 'https://lukaszmical.pl'
).replace(/\/$/, '');

export const siteName = 'Łukasz Micał';

// Default social-share image, generated by `src/app/opengraph-image.tsx`.
export const ogImage = '/opengraph-image';

// Build a locale-prefixed path following the `as-needed` strategy: the default
// locale has no prefix, the others are prefixed with `/<locale>`.
export function localePath(locale: Locale, path = ''): string {
    const clean = path === '/' ? '' : path.replace(/\/$/, '');
    const prefix = locale === defaultLocale ? '' : `/${locale}`;
    return `${prefix}${clean}` || '/';
}

export function localeUrl(locale: Locale, path = ''): string {
    return `${siteUrl}${localePath(locale, path)}`;
}

// Canonical (for the current locale) plus hreflang alternates for every locale.
// Paths are relative — Next resolves them against `metadataBase`.
export function buildAlternates(
    locale: Locale,
    path = '',
): Metadata['alternates'] {
    return {
        canonical: localePath(locale, path),
        languages: {
            ...Object.fromEntries(
                locales.map((item) => [item, localePath(item, path)]),
            ),
            'x-default': localePath(defaultLocale, path),
        },
    };
}

// Metadata for a static localized page whose namespace exposes `title` and
// `description` message keys.
export async function metadataForPage(
    locale: Locale,
    namespace: string,
    path: string,
): Promise<Metadata> {
    const t = await getTranslations({locale, namespace});
    const title = t('title');
    const description = t('description');

    return {
        title,
        description,
        alternates: buildAlternates(locale, path),
        openGraph: {
            title,
            description,
            url: localePath(locale, path),
            images: [ogImage],
        },
        twitter: {images: [ogImage]},
    };
}

// Metadata for a CMS entry at `path`. The homepage (`/`) uses its title as is,
// other entries get the site name appended.
export function entryMetadata(
    entry: {
        title: string;
        description: string;
        cover: string | null;
        published: boolean;
    },
    locale: Locale,
    path: string,
): Metadata {
    const title =
        entry.title && path !== '/' ? `${entry.title} | ${siteName}` : entry.title || siteName;
    const description = entry.description || undefined;

    return {
        title,
        description,
        robots: entry.published ? undefined : {index: false, follow: false},
        alternates: buildAlternates(locale, path),
        openGraph: {
            type: path === '/' ? 'website' : 'article',
            title,
            description,
            url: localePath(locale, path),
            images: [entry.cover ?? ogImage],
        },
        twitter: {images: [entry.cover ?? ogImage]},
    };
}

// Metadata for a draft: never exposes the real title/description (whoever is
// looking, admin included), but still explicitly noindexes it — a safety net
// on top of the login gate, in case a draft URL ever leaks.
export const draftMetadata: Metadata = {
    robots: {index: false, follow: false},
};

const author = {
    '@type': 'Person',
    name: siteName,
    url: siteUrl,
};

// schema.org Person for the site owner (used on the homepage).
export function personJsonLd(): Record<string, unknown> {
    return {
        '@context': 'https://schema.org',
        ...author,
        jobTitle: 'Frontend Developer',
    };
}

// schema.org CreativeWork for a single entry.
export function entryJsonLd(
    entry: {title: string; description: string; cover: string | null},
    locale: Locale,
    path: string,
): Record<string, unknown> {
    return {
        '@context': 'https://schema.org',
        '@type': 'CreativeWork',
        name: entry.title,
        description: entry.description || undefined,
        url: localeUrl(locale, path),
        inLanguage: locale,
        image: entry.cover || undefined,
        author,
    };
}
